import{_ as e,a0 as a,w as r,s as d,ao as n,I as p,x as i,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const c=JSON.parse('{"title":"Linux終端下 dstat 監控工具 | LCTT x X-CMD","titleTemplate":false,"description":"Linux終端下 dstat 監控工具 | LCTT (201406) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux終端下 dstat 監控工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux終端下 dstat 監控工具 | LCTT (201406) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201406/Linux Terminal--Dstat monitoring tools","title":"Linux終端下 dstat 監控工具","tag":"201406","desc":""},"relativePath":"201406/Linux Terminal--Dstat monitoring tools.md","filePath":"[post].md"}'),u={name:"201406/Linux Terminal--Dstat monitoring tools.md"};function m(x,t,T,g,f,C){const l=a("Link");return r(),d("div",null,[t[14]||(t[14]=n(`<h1 id="linux終端下-dstat-監控工具" tabindex="-1">Linux終端下 dstat 監控工具 <a class="header-anchor" href="#linux終端下-dstat-監控工具" aria-label="Permalink to “Linux終端下 dstat 監控工具”">​</a></h1><p>dstat 是一個可以取代vmstat，iostat，netstat和ifstat這些命令的多功能產品。dstat克服了這些命令的侷限並增加了一些另外的功能，增加了監控項，也變得更靈活了。dstat可以很方便監控系統運行狀況並用於基準測試和排除故障。</p><p>dstat可以讓你實時地看到所有系統資源，例如，你能夠通過統計IDE控制器當前狀態來比較磁盤利用率，或者直接通過網絡帶寬數值來比較磁盤的吞吐率（在相同的時間間隔內）。</p><p>dstat將以列表的形式為你提供選項信息並清晰地告訴你是在何種幅度和單位顯示輸出。這樣更好地避免了信息混亂和誤報。更重要的是，它可以讓你更容易編寫插件來收集你想要的數據信息，以從未有過的方式進行擴展。</p><p>Dstat的默認輸出是專門為人們實時查看而設計的，不過你也可以將詳細信息通過CSV輸出到一個文件，並導入到Gnumeric或者Excel生成表格中。</p><p>###特性###</p><ul><li>結合了vmstat，iostat，ifstat，netstat以及更多的信息</li><li>實時顯示統計情況</li><li>在分析和排障時可以通過啓用監控項並排序</li><li>模組化設計</li><li>使用python編寫的，更方便擴展現有的工作任務</li><li>容易擴展和添加你的計數器（請為此做出貢獻）</li><li>包含的許多擴展插件充分説明了增加新的監控項目是很方便的</li><li>可以分組統計塊設備/網絡設備，並給出總數</li><li>可以顯示每台設備的當前狀態</li><li>極準確的時間精度，即便是系統負荷較高也不會延遲顯示</li><li>顯示準確地單位和和限制轉換誤差範圍</li><li>用不同的顏色顯示不同的單位</li><li>顯示中間結果延時小於1秒</li><li>支持輸出CSV格式報表，並能導入到Gnumeric和Excel以生成圖形</li></ul><h3 id="安裝方法" tabindex="-1">安裝方法 <a class="header-anchor" href="#安裝方法" aria-label="Permalink to “安裝方法”">​</a></h3><p>Ubuntu/Mint和Debin系統：</p><p>本地軟件庫中有相關安裝包，你可以用下面命令安裝：</p><pre><code># sudo apt-get install dstat
</code></pre><p>RHEL/Centos和Fedora系統:</p>`,12)),p("p",null,[t[1]||(t[1]=i("你可以在romforge軟件庫中添加有相關安裝包，參照",-1)),o(l,{href:"http://www.tecmint.com/install-and-enable-rpmforge-repository-in-rhel-centos-6-5-4/"},{default:s(()=>[...t[0]||(t[0]=[i("指導",-1)])]),_:1}),t[2]||(t[2]=i("，使用如下命令很簡單就能進行安裝：",-1))]),t[15]||(t[15]=n(`<pre><code>   # yum install dstat
</code></pre><p>ArchLinux系統：</p><p>相關軟件包在社區資源庫中，你可以用這個命令來安裝：</p><pre><code># pacman -S dstat
</code></pre><p>###使用方法 ###</p><p>dstat的基本用法就是輸入dstat命令，輸出如下：</p><p><img src="http://cdn.linuxaria.com/wp-content/uploads/2014/05/dstat.png" alt=""></p><p>這是默認輸出顯示的信息：</p><p><strong>CPU狀態</strong>：CPU的使用率。這項報告更有趣的部分是顯示了用户，系統和空閒部分，這更好地分析了CPU當前的使用狀況。如果你看到&quot;wait&quot;一欄中，CPU的狀態是一個高使用率值，那説明系統存在一些其它問題。當CPU的狀態處在&quot;waits&quot;時，那是因為它正在等待I/O設備（例如內存，磁盤或者網絡）的響應而且還沒有收到。</p><p><strong>磁盤統計</strong>：磁盤的讀寫操作，這一欄顯示磁盤的讀、寫總數。</p><p><strong>網絡統計</strong>：網絡設備發送和接受的數據，這一欄顯示的網絡收、發數據總數。</p><p><strong>分頁統計</strong>：系統的分頁活動。分頁指的是一種內存管理技術用於查找系統場景，一個較大的分頁表明系統正在使用大量的交換空間，或者説內存非常分散，大多數情況下你都希望看到page in（換入）和page out（換出）的值是0 0。</p><p><strong>系統統計</strong>：這一項顯示的是中斷（int）和上下文切換（csw）。這項統計僅在有比較基線時才有意義。這一欄中較高的統計值通常表示大量的進程造成擁塞，需要對CPU進行關注。你的服務器一般情況下都會運行運行一些程序，所以這項總是顯示一些數值。</p><p>默認情況下，dstat每秒都會刷新數據。如果想退出dstat，你可以按&quot;CTRL-C&quot;鍵。</p><p>需要注意的是報告的第一行，通常這裏所有的統計都不顯示數值的。</p><p>這是由於dstat會通過上一次的報告來給出一個總結，所以第一次運行時是沒有平均值和總值的相關數據。</p><p>但是dstat可以通過傳遞2個參數運行來控制報告間隔和報告數量。例如，如果你想要dstat輸出默認監控、報表輸出的時間間隔為3秒鐘,並且報表中輸出10個結果，你可以運行如下命令：</p><pre><code>dstat 3 10
</code></pre><p>在dstat命令中有很多參數可選，你可以通過man dstat命令查看，大多數常用的參數有這些：</p><ul><li>-l ：顯示負載統計量</li><li>-m ：顯示內存使用率（包括used，buffer，cache，free值）</li><li>-r ：顯示I/O統計</li><li>-s ：顯示交換分區使用情況</li><li>-t ：將當前時間顯示在第一行</li><li>–fs ：顯示文件系統統計數據（包括文件總數量和inodes值）</li><li>–nocolor ：不顯示顏色（有時候有用）</li><li>–socket ：顯示網絡統計數據</li><li>–tcp ：顯示常用的TCP統計</li><li>–udp ：顯示監聽的UDP接口及其當前用量的一些動態數據</li></ul><p>當然不止這些用法，dstat附帶了一些<strong>插件</strong>很大程度地擴展了它的功能。你可以通過查看/usr/share/dstat目錄來查看它們的一些使用方法，常用的有這些：</p><ul><li>-–disk-util ：顯示某一時間磁盤的忙碌狀況</li><li>-–freespace ：顯示當前磁盤空間使用率</li><li>-–proc-count ：顯示正在運行的程序數量</li><li>-–top-bio ：指出塊I/O最大的進程</li><li>-–top-cpu ：圖形化顯示CPU佔用最大的進程</li><li>-–top-io ：顯示正常I/O最大的進程</li><li>-–top-mem ：顯示佔用最多內存的進程</li></ul><p>舉一些例子：</p><p>查看全部內存都有誰在佔用：</p><pre><code>dstat -g -l -m -s --top-mem
</code></pre><p>顯示一些關於CPU資源損耗的數據：</p><pre><code>dstat -c -y -l --proc-count --top-cpu
</code></pre><p>###如何輸出一個csv文件###</p><p>想輸出一個csv格式的文件用於以後，可以通過下面的命令：</p><pre><code># dstat –output /tmp/sampleoutput.csv -cdn
</code></pre><hr>`,31)),p("p",null,[t[4]||(t[4]=i("via: ",-1)),o(l,{href:"http://linuxaria.com/howto/linux-terminal-dstat-monitoring-tools"},{default:s(()=>[...t[3]||(t[3]=[i("http://linuxaria.com/howto/linux-terminal-dstat-monitoring-tools",-1)])]),_:1})]),p("p",null,[t[7]||(t[7]=i("譯者：",-1)),o(l,{href:"https://github.com/disylee"},{default:s(()=>[...t[5]||(t[5]=[i("disylee",-1)])]),_:1}),t[8]||(t[8]=i(" 校對：",-1)),o(l,{href:"https://github.com/wxy"},{default:s(()=>[...t[6]||(t[6]=[i("wxy",-1)])]),_:1})]),p("p",null,[t[11]||(t[11]=i("本文由 ",-1)),o(l,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[9]||(t[9]=[i("LCTT",-1)])]),_:1}),t[12]||(t[12]=i(" 原創翻譯，",-1)),o(l,{href:"http://linux.cn/"},{default:s(()=>[...t[10]||(t[10]=[i("Linux中國",-1)])]),_:1}),t[13]||(t[13]=i(" 榮譽推出",-1))])])}const D=e(u,[["render",m]]);export{c as __pageData,D as default};
